const germanEntries = Object.entries(german).sort(([left], [right]) => right.length - left.length)

export function translate(value: string, language: Language): string {
  if (language === 'en') return value
  const exact = german[value]
  if (exact) return exact
  const repPhrase = value.match(/^(\d+) reps?$/)
  if (repPhrase) return `${repPhrase[1]} ${repPhrase[1] === '1' ? 'Wiederholung' : 'Wiederholungen'}`
  const level = value.match(/^(Beginner|Intermediate|Advanced) · Level (\d+)$/)
  if (level) return `${german[level[1]]} · Level ${level[2]}`
  const confidence = value.match(/^Mean landmark confidence · (\d+)%$/)
  if (confidence) return `Mittlere Sicherheit der Körperpunkte · ${confidence[1]}%`
  let partial = value
    .replace(/^Handstand Combo$/, 'Handstand-Combo')
    .replace(/^Selected exercise$/, 'Ausgewählte Übung')
    .replace(/^Could not (.*)$/, 'Konnte $1 nicht')
    .replace(/^Error: /, 'Fehler: ')
    .replace(/(\d+) reps?\b/g, (_, count: string) => `${count} ${count === '1' ? 'Wiederholung' : 'Wiederholungen'}`)
    .replace(/(\d+) analyzed intervals/g, '$1 analysierte Abschnitte')
    .replace(/(\d+) higher-confidence repetitions/g, '$1 Wiederholungen mit höherer Sicherheit')
    .replace(/(\d+) planned steps/g, '$1 geplante Schritte')
    .replace(/(\d+) scored sessions/g, '$1 bewertete Trainings')
    .replace(/(\d+) intervals · no overall score/g, '$1 Abschnitte · keine Gesamtbewertung')
    .replace(/(\d+) frames had low or missing landmark confidence/g, '$1 Frames mit niedriger oder fehlender Sicherheit der Körperpunkte')
    .replace(/(\d+) movement phases? did not meet the completion criteria/g, '$1 Bewegungsphasen erfüllten die Abschlusskriterien nicht')
    .replace(/(\d+) partial/g, '$1 teilweise')
    .replace(/(\d+) repetitions · /g, '$1 Wiederholungen · ')
    .replace(/Repetitions for step (\d+)/g, 'Wiederholungen für Schritt $1')
    .replace(/Hold time for step (\d+)/g, 'Haltezeit für Schritt $1')
    .replace(/Move step (\d+) up/g, 'Schritt $1 nach oben verschieben')
    .replace(/Move step (\d+) down/g, 'Schritt $1 nach unten verschieben')
    .replace(/Remove step (\d+)/g, 'Schritt $1 entfernen')
    .replace(/Delete (.+) session/g, 'Training „$1“ löschen')
    .replace(/Estimated alignment signal: (\d+)\/100 \(not a technique score\)\./g, 'Geschätztes Ausrichtungssignal: $1/100 (keine Technikbewertung).')
    .replace(/An inverted interval of about ([\d.]+)s was estimated against a ([\d.]+)s target; review the body line and timing\./g, 'Ein umgekehrter Abschnitt von etwa $1 s wurde mit einem Ziel von $2 s verglichen; prüfe Körperlinie und Zeitmessung.')
    .replace(/(\d+) elbow flexion-extension cycles? detected against (\d+) requested; verify the count and depth\./g, '$1 Ellbogen-Beuge-Streck-Zyklen bei $2 angeforderten Wiederholungen erkannt; prüfe Anzahl und Tiefe.')
    .replace(/Record from the recommended angle: /g, 'Nimm aus der empfohlenen Perspektive auf: ')
    .replace(/Keep practicing (.+) with the same camera setup for comparable results\./g, 'Übe $1 weiter mit derselben Kameraeinstellung, damit die Ergebnisse vergleichbar bleiben.')
    .replace(/Focus on: /g, 'Fokus: ')
    .replace(/^Delete combo “(.+)”\?$/, 'Combo „$1“ löschen?')

  for (const [source, target] of germanEntries) {
    if (source.length > 3 && partial.includes(source)) partial = partial.replaceAll(source, target)
  }
  return partial
}
